// src/features/inbox/pushText.ts
function fill(template, vars) {
  return Object.entries(vars).reduce((s, [k, v]) => s.split(`{${k}}`).join(String(v)), template);
}
function pushText(text, opts) {
  const dict = TEXTS[opts.language];
  const t = (key) => dict[key] ?? TEXTS.es[key];
  const parsed = parseUtterance(text, opts.today);
  const income = parsed.type === "income";
  const concept = parsed.concept.trim();
  let what;
  if (parsed.amount == null) {
    what = concept ? fill(t(income ? "inbox.pushIncomeNoAmount" : "inbox.pushNoAmount"), { concept }) : t("inbox.pushUnreadable");
  } else {
    const amount = formatMoney(parsed.amount, parsed.currency ?? opts.currency);
    what = concept ? fill(t(income ? "inbox.pushIncome" : "inbox.pushExpense"), { amount, concept }) : fill(t(income ? "inbox.pushIncomeNoConcept" : "inbox.pushExpenseNoConcept"), { amount });
  }
  const tap = opts.pending > 1 ? fill(t("inbox.pushTapMany"), { n: opts.pending }) : t("inbox.pushTapOne");
  return { title: "Step up", body: `${what}
${tap}` };
}
export {
  pushText
};
